    37→        q{Rule => 'foo'},    # Perl arrow
    38→        q{Rule = 'foo'},     # Assignment
    39→        q{Rule -- 'foo'},    # Double dash
    40→    );
    41→
    42→    for my $bnf (@invalid) {
    43→        eval { Chalk::BNF::parse_bnf_string($bnf) };
