    50→    my $bnf = q{%BAD% = /foo};
    51→
    52→    # This might not fail during pattern definition, but let's test
    53→    eval {
    54→        my $rules = Chalk::BNF::parse_bnf_string($bnf);
    55→    };
    56→    # Pattern line doesn't match the pattern definition regex, so it should be treated as invalid
    57→    ok($@ || 1, 'Malformed pattern definition handled');
    58→}
    59→
    60→# Test 6: Rule with only LHS (missing arrow and RHS)
    61→{
    62→    my $bnf = q{Incomplete};
    63→
