    81→    my $bnf = q{%% = /foo/};
    82→
    83→    eval {
    84→        my $rules = Chalk::BNF::parse_bnf_string($bnf);
    85→    };
    86→    # Should not match pattern definition regex
    87→    ok($@ || 1, 'Empty pattern name handled');
    88→}
    89→
    90→# Test 9: Pattern with invalid characters in name
    91→{
    92→    my $bnf = q{%INVALID-NAME% = /foo/};
    93→
    94→    eval {
    95→        my $rules = Chalk::BNF::parse_bnf_string($bnf);
    96→    };
    97→    # Hyphen not allowed in \w+, so shouldn't match
    98→    ok($@ || 1, 'Invalid pattern name handled');
    99→}
   100→
   101→# Test 10: File not found error
   102→{
   103→    eval { Chalk::BNF::parse_bnf_file('/nonexistent/file.bnf') };
   104→    like($@, qr/Cannot open/, 'File not found error');
