# Test 2: Build grammar with explicit start symbol
{
    my $bnf = <<'EOF';
Expr -> Term
Term -> Number
Number -> /\d+/
EOF

    my $grammar = Chalk::BNF::build_chalk_grammar($bnf, 'Number');

