lib/Chalk/
  BNF.pm                            # ✅ Already exists - BNF parser
  Grammar.pm                        # ✅ Modify: Support rules_package
  Parser.pm                         # ✅ Modify: Call semantic actions during completion

  EvalContext.pm                    # ⚠️  NEW: Comonad context

  Grammar/
