```

## Evaluation Context (Comonad)

```perl
package Chalk::EvalContext;
use experimental 'class';

class Chalk::EvalContext {
    field $focus :param :reader;        # Current semantic value (from children)
    field $children :param :reader;     # Child contexts (for extend/duplicate)
    field $start_pos :param :reader;    # Parse span start
    field $end_pos :param :reader;      # Parse span end
    field $env :param :reader;          # Symbol table / environment
    field $grammar :param :reader;      # Grammar reference
    field $rule :param :reader;         # Rule being evaluated

    # Comonad: extract
    # Get the value at the current focus (synthesized attribute)
    method extract() {
        return $focus;
    }

    # Comonad: extend
    # Apply function over the entire context structure
    # Used for attribute grammars where parent affects children
    method extend($f) {
        my $new_focus = $f->($self);
        my @new_children = map { $_->extend($f) } @$children;

        return Chalk::EvalContext->new(
            focus => $new_focus,
            children => \@new_children,
            start_pos => $start_pos,
            end_pos => $end_pos,
            env => $env,
            grammar => $grammar,
            rule => $rule
        );
    }

    # Comonad: duplicate
    # Create nested context (context of contexts)
    # Used for inherited attributes that flow down the tree
    method duplicate() {
        my @duplicated_children = map { $_->duplicate } @$children;

        return Chalk::EvalContext->new(
            focus => $self,  # Focus is now the entire context
            children => \@duplicated_children,
            start_pos => $start_pos,
            end_pos => $end_pos,
            env => $env,
            grammar => $grammar,
            rule => $rule
        );
    }

    # Functor: fmap (required for comonad)
    method fmap($f) {
        return Chalk::EvalContext->new(
            focus => $f->($focus),
            children => $children,  # Structure preserved
            start_pos => $start_pos,
            end_pos => $end_pos,
            env => $env,
            grammar => $grammar,
            rule => $rule
        );
    }

    # Convenience accessors
    method child($index) { 
        return $children->[$index]->extract if $index < @$children;
        return undef;
    }

    method child_context($index) {
        return $children->[$index] if $index < @$children;
        return undef;
    }

    method env_lookup($name) { $env->{$name} }

    method env_bind($name, $value) { 
        # Return new context with updated environment (immutable)
        my %new_env = (%$env, $name => $value);
        return Chalk::EvalContext->new(
            focus => $focus,
            children => $children,
            start_pos => $start_pos,
            end_pos => $end_pos,
            env => \%new_env,
            grammar => $grammar,
            rule => $rule
        );
    }

    method span() { [$start_pos, $end_pos] }
}

1;
```

## Semantic Semiring

The semiring carries semantic values alongside parsing information:

```perl
package Chalk::Semiring::Semantic;
use experimental 'class';

class Chalk::Semiring::SemanticElement :isa(Chalk::Element) {
    field $value :param :reader;         # Semantic value from evaluation
    field $context :param :reader;       # Evaluation context (for nested eval)
    field $sppf_node :param = undef;     # Optional SPPF (for debugging/AST mode)

    method add($other, $swap = undef) {
        # Choice: prefer higher-scoring alternative
        # In ambiguous parses, keep both (SPPF tracks alternatives)
        return $self;  # TODO: Handle ambiguity properly
    }

    method multiply($other, $swap = undef) {
        # Sequence: combine contexts
        # This will be called during scan/complete
        # The actual semantic action happens in complete()
        return Chalk::Semiring::SemanticElement->new(
            value => undef,  # Not yet evaluated
            context => $self->context->extend(sub ($ctx) {
                # Combine child contexts for parent evaluation
                my @combined_children = ($ctx, $other->context);
                return \@combined_children;
            })
        );
    }

    method equals($other, $swap = undef) {
        return 0 unless ref($other) eq ref($self);
        return $value == $other->value;  # Simplified
    }

    method to_string(@) {
        return "Semantic[$value]";
    }
}

class Chalk::Semiring::Semantic :isa(Chalk::Semiring) {
    field $env :param = {};              # Initial environment
    field $grammar :param :reader;       # Grammar reference
    field $mul_id :reader;
    field $add_id :reader;

    ADJUST {
        # Identity elements
        my $empty_context = Chalk::EvalContext->new(
            focus => undef,
            children => [],
            start_pos => 0,
            end_pos => 0,
            env => $env,
            grammar => $grammar,
            rule => undef
        );

        $mul_id = Chalk::Semiring::SemanticElement->new(
            value => undef,  # ε - no value
            context => $empty_context
        );

        $add_id = Chalk::Semiring::SemanticElement->new(
            value => undef,  # ⊥ - failed parse
            context => $empty_context
        );
    }

    method init_element_from_rule($rule, $start_pos = 0, $end_pos = 0) {
        # Create element with context for this rule
        # Value not yet computed - happens during completion
        my $context = Chalk::EvalContext->new(
            focus => undef,
            children => [],
            start_pos => $start_pos,
            end_pos => $end_pos,
            env => $env,
            grammar => $grammar,
            rule => $rule
        );

        return Chalk::Semiring::SemanticElement->new(
            value => undef,
            context => $context
        );
    }
}

1;
```

## Modified Parser: Calling Semantic Actions During Completion

```perl
# In Chalk::Parser::complete()
method complete($completed_item, $completed_element, $chart, $agenda) {
    # ... existing completion logic ...

    # NEW: Call semantic action when rule completes
    my $rule = $completed_item->rule;

    if ($rule->can('evaluate') && $completed_element isa Chalk::Semiring::SemanticElement) {
        # Collect evaluated child values from chart
        my @child_contexts;
        for my $waiting_item ($chart->items_waiting_for($rule->lhs, $completed_item->start_pos)) {
            my $waiting_element = $chart->get_element($waiting_item);
            if ($waiting_element && $waiting_element isa Chalk::Semiring::SemanticElement) {
                push @child_contexts, $waiting_element->context;
            }
        }

        # Build context for this completion
        my $eval_context = Chalk::EvalContext->new(
            focus => undef,  # Will be set by extract after evaluation
            children => \@child_contexts,
            start_pos => $completed_item->start_pos,
            end_pos => $completed_item->end_pos,
            env => $completed_element->context->env,
            grammar => $grammar,
            rule => $rule
        );

        # Call semantic action
        my $semantic_value = $rule->evaluate($eval_context);

        # Update element with computed value
        $completed_element = Chalk::Semiring::SemanticElement->new(
            value => $semantic_value,
            context => $eval_context->fmap(sub { $semantic_value }),
            sppf_node => $completed_element->sppf_node
        );
    }

    # ... rest of existing completion logic with updated element ...
}
```

## Rule Subclass Example

```perl
package Chalk::Grammar::Perl::Rule::Expression;
use experimental 'class';

class Chalk::Grammar::Perl::Rule::Expression :isa(Chalk::GrammarRule) {
    method evaluate($context) {
        my $rhs = $self->rhs;

        # Dispatch based on this rule instance's RHS structure
        if (@$rhs == 1 && $rhs->[0] eq 'Number') {
            return $self->passthrough($context);
        }
        elsif (@$rhs == 3 && $rhs->[1] eq '+') {
            return $self->add($context);
        }
        elsif (@$rhs == 3 && $rhs->[1] eq '-') {
            return $self->subtract($context);
        }
        elsif (@$rhs == 3 && $rhs->[0] eq '(' && $rhs->[2] eq ')') {
            return $self->parens($context);
        }

        # Fallback: just return children as list (for AST construction)
        return [$context->children->@*];
    }

    # Synthesized attribute: simple value computation
    method passthrough($ctx) { $ctx->child(0) }
    method add($ctx)         { $ctx->child(0) + $ctx->child(2) }
    method subtract($ctx)    { $ctx->child(0) - $ctx->child(2) }
    method parens($ctx)      { $ctx->child(1) }
}

1;
```

## Advanced: Attribute Grammar with Inherited Attributes

Using comonad's `extend` and `duplicate` for inherited attributes:

```perl
class Chalk::Grammar::Perl::Rule::VariableDecl :isa(Chalk::GrammarRule) {
    method evaluate($context) {
        my $rhs = $self->rhs;

        # Example: 'my' Variable '=' Expression
        if (@$rhs == 4 && $rhs->[0] eq 'my') {
            my $var_name = $context->child(1);  # Variable name
            my $expr_value = $context->child(3);  # Expression value

            # Update environment (synthesized attribute flowing up)
            my $new_context = $context->env_bind($var_name, $expr_value);

            # Return value AND updated context
            return $new_context;
        }

        return $context;
    }
}

# For inherited attributes (parent → child), use extend:
method evaluate_with_type_context($context) {
    # Extend context to propagate type information down
    return $context->extend(sub ($ctx) {
        # Each child gets parent's type context
        my $parent_type = $ctx->env_lookup('expected_type');
        return $ctx->env_bind('expected_type', $parent_type);
    });
}
```

## Enhanced Grammar Loading

Extend `Chalk::BNF::build_chalk_grammar()` to support rule subclasses:

```perl
sub build_chalk_grammar($bnf_content, $start_symbol = undef, %opts) {
    my $rules = parse_bnf_string($bnf_content);
    my $rules_package = $opts{rules_package};  # NEW

    # If start symbol specified, ensure it's first
    if (defined $start_symbol) {
        my @ordered_rules = (
            (grep { $_->[0] eq $start_symbol } @$rules),
            (grep { $_->[0] ne $start_symbol } @$rules)
        );
        $rules = \@ordered_rules;
    }

    # Build grammar with rule subclasses
    my %grammar_rules;
    for my $rule_spec (@$rules) {
        my ($lhs, $rhs, $prob) = @$rule_spec;

        my $rule;
        if ($rules_package) {
            # Try to load rule subclass
            my $rule_class = "${rules_package}::Rule::${lhs}";
            eval "require $rule_class; 1" or do {
                # Subclass doesn't exist, use base class
                $rule = Chalk::GrammarRule->new(
                    lhs => $lhs,
                    rhs => $rhs,
                    probability => $prob // 1.0
                );
            };

            if (!$@) {
                # Subclass exists, instantiate it
                $rule = $rule_class->new(
                    lhs => $lhs,
                    rhs => $rhs,
                    probability => $prob // 1.0
                );
            }
        } else {
            # No rules package, use base class
            $rule = Chalk::GrammarRule->new(
                lhs => $lhs,
                rhs => $rhs,
                probability => $prob // 1.0
            );
        }

        push @{ $grammar_rules{$lhs} //= [] }, $rule;
    }

    return Chalk::Grammar->new(
        rules => \%grammar_rules,
        start_symbol => $rules[0]->[0]
    );
}
```

## Usage Example

```perl
use Chalk::BNF;
use Chalk::Parser;
use Chalk::Semiring::Semantic;

# Load grammar with semantic actions
