  ```perl
  package Chalk::Grammar::BNF;
  use 5.42.0;
  use experimental 'class';
  use Chalk::Grammar;

  # Export singleton grammar instance
  our $grammar;

  sub grammar() { return $grammar; }

  # Hand-coded BNF grammar rules
  $grammar = Chalk::Grammar->build_grammar(
      rules => [
          # Top level
          ['Grammar' => ['LineList']],

          # Lines
          ['LineList' => []],  # Empty
          ['LineList' => ['Line', 'LineList']],

          ['Line' => ['PatternDef']],
          ['Line' => ['GrammarRule']],
          ['Line' => ['Comment']],
          ['Line' => ['BlankLine']],

          # Pattern definitions: %NAME% = /regex/flags
          ['PatternDef' => [
              '%', qr/[a-zA-Z_]\w*/, '%',
              qr/\s*/, '=', qr/\s*/,
              '/', qr/(?:[^\/\\]|\\.)+/, '/',
              qr/[a-z]*/  # Optional flags
          ]],

          # Grammar rules: LHS -> RHS
          ['GrammarRule' => [
              qr/[a-zA-Z_]\w*/,  # LHS (nonterminal)
              qr/\s*/,
              '->',
              qr/\s*/,
              'RHS'
          ]],

          # Right-hand side
          ['RHS' => ['RHSElementList']],

          ['RHSElementList' => ['RHSElement']],
          ['RHSElementList' => ['RHSElement', qr/\s+/, 'RHSElementList']],

          # RHS elements
          ['RHSElement' => ['Terminal']],
          ['RHSElement' => ['Nonterminal']],
          ['RHSElement' => ['PatternRef']],

          # Terminals: 'string'
          ['Terminal' => ["'", qr/(?:[^'\\]|\\.)*/, "'"]],

          # Nonterminals: IDENT (but not in quotes)
          ['Nonterminal' => [qr/[a-zA-Z_]\w*/]],

          # Pattern references: %NAME%
          ['PatternRef' => ['%', qr/[a-zA-Z_]\w*/, '%']],

          # Comments and blank lines
          ['Comment' => [qr/#[^\n]*/]],
          ['BlankLine' => [qr/\n/]],
      ]
  );

  1;
  ```

