- [ ] **`Chalk::Grammar::BNF::Rule::RHS`**
  ```perl
  class Chalk::Grammar::BNF::Rule::RHS :isa(Chalk::GrammarRule) {
      method evaluate($context) {
          # Flatten RHSElementList into array
          my $element_list = $context->child(0);
          my @elements;

          while (defined $element_list && ref($element_list) eq 'ARRAY') {
              my ($elem, $rest) = @$element_list;
              push @elements, $elem if defined $elem;
              $element_list = $rest;
          }

          return \@elements;
      }
  }
